import type { EffortLevel, Options } from "@anthropic-ai/claude-agent-sdk";

type Route = { model: string; effort: EffortLevel };

export const ROUTES: Record<string, Route> = {
  readiness: { model: "claude-sonnet-5-5", effort: "low" },
  plan: { model: "claude-opus-5-5", effort: "medium" },
  build: { model: "claude-opus-5-5", effort: "medium" },
  helper: { model: "claude-haiku-5-5", effort: "medium" },
  "ci-fix": { model: "claude-opus-5-5", effort: "low" },
};
const LEVELS: EffortLevel[] = ["low", "medium", "high", "xhigh"];

export const routeFor = (job: string): Route => ROUTES[job] ?? ROUTES.build!;
export const oneLevelUp = (effort: EffortLevel): EffortLevel =>
  LEVELS[Math.min(LEVELS.indexOf(effort) + 1, LEVELS.length - 1)]!;

export const optionsFor = (job: string): Options => {
  const { model, effort } = routeFor(job);
  return { model, effort, permissionMode: "dontAsk", env: { ...process.env, CLAUDE_CODE_PROMPT_CACHE_TTL: "5m" } };
};

import type { EffortLevel, Query, SDKUserMessage } from "@anthropic-ai/claude-agent-sdk";
import { oneLevelUp } from "./routing.js";

async function* say(text: string): AsyncIterable<SDKUserMessage> {
  yield { type: "user", message: { role: "user", content: text }, parent_tool_use_id: null };
}

// The step's checks failed: try once more, one level up, in the SAME session.
export const rerunOneLevelUp = async (session: Query, effort: EffortLevel, retry: string) => {
  const higher = oneLevelUp(effort);
  await session.applyFlagSettings({ effortLevel: higher });
  await session.streamInput(say(retry));
  return higher;
};

