const STEPS = ["ticket", "plan", "plan_ok", "vm", "build", "pr", "byte", "approve", "learn"] as const;
export type Step = (typeof STEPS)[number];

export const stepEnv = (run: { agent: string; jira: string; id: string }, step: Step): Record<string, string> => {
  const tags = { agent: run.agent, jira: run.jira, run: run.id, step };
  return {
    OTEL_RESOURCE_ATTRIBUTES: Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(","),
    ANTHROPIC_CUSTOM_HEADERS: `x-ai-agents-step: ${step}`,
  };
};

// test/step-env.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import { optionsFor } from "../src/routing.js";
import { stepEnv } from "../src/step-env.js";

test("every signal of a step carries the same tags", () => {
  const env = stepEnv({ agent: "nova", jira: "RH-1234", id: "r-42" }, "build");
  assert.equal(env.OTEL_RESOURCE_ATTRIBUTES, "agent=nova,jira=RH-1234,run=r-42,step=build");
  assert.equal(env.ANTHROPIC_CUSTOM_HEADERS, "x-ai-agents-step: build");
});

test("env keeps PATH and HOME, because it replaces the whole environment", () => {
  const env = optionsFor("plan").env!;
  assert.equal(env.PATH, process.env.PATH);
  assert.equal(env.HOME, process.env.HOME);
});
